package com.atlasiq.enterprise;
import jakarta.enterprise.context.ApplicationScoped;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.HexFormat;
@ApplicationScoped public class WebhookSecurity {public String sign(String secret,String payload){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return "sha256="+HexFormat.of().formatHex(m.doFinal(payload.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public URI validateDestination(String url){URI u=URI.create(url);if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null)throw new IllegalArgumentException("HTTPS webhook required");try{for(InetAddress a:InetAddress.getAllByName(u.getHost()))if(a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress())throw new IllegalArgumentException("private/local webhook destinations are forbidden");}catch(UnknownHostException e){throw new IllegalArgumentException("unresolvable webhook host");}return u;}}
